# Cusco / Qusqu: spots of daily life, events and stories. See tools/content/cities/FORMAT.md.
import math

KILLKE = ["killke-1300"]
IMPERIAL = ["pachacuti-1470", "huayna-1530"]
COLONIAL = ["colonial-1650"]

P0 = (-13.5166, -71.9787)
KX, KY = 111320.0 * math.cos(math.radians(13.52)), 110950.0


def UV(u, v):
    """(lat, lon) of a point u metres south-east and v metres north-east of the middle of the plaza."""
    e = 0.7071 * (u + v)
    n = 0.7071 * (v - u)
    return (round(P0[0] + n / KY, 5), round(P0[1] + e / KX, 5))


